<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {useServiceContext} from '@/composables/useServiceContext'
import {isPage,isOrganization,isFeatured,isPublicItem,query,publicLink,capabilities,type Organization,type Featured,type Json} from '@/api/modules/clientServices'
import {directoryCity} from '@/business/directoryCity'
import ServiceWorkspace from '@/components/ServiceWorkspace.vue'
import OrganizationCover from '@/components/OrganizationCover.vue'
const route=useRoute(),ui=useServiceContext(()=>null),{error,notice}=ui,featured=computed(()=>route.meta.directoryView==='featured'),partyId=computed(()=>String(route.params.partyId||''))
const city=ref(directoryCity.value),term=ref(''),organizations=ref<Organization[]>([]),features=ref<Featured[]>([]),organization=ref<Organization|null>(null),notices=ref<Json[]>([]),cursor=ref<string|number|null>(null),noticeCursor=ref<string|number|null>(null),loading=ref(false),loaded=ref(false)
let initialized=false
function initialize(){initialized=true;void load()}
let serial=0
function clear(){ui.cancelReads();error.value=null;serial++;organizations.value=[];features.value=[];organization.value=null;notices.value=[];cursor.value=noticeCursor.value=null;loaded.value=false;loading.value=false}
async function load(more=false){error.value=null;if(loading.value||more&&!cursor.value)return;const n=++serial;loading.value=true;if(!more){organizations.value=[];features.value=[];organization.value=null;notices.value=[];cursor.value=noticeCursor.value=null;loaded.value=false}
 if(partyId.value){const id=partyId.value,r=await ui.read('/directory/organizations/'+id,(v):v is Organization=>isOrganization(v)&&v.party_id===id);if(n!==serial)return;organization.value=r;if(r)await loadNotices();loaded.value=true;loading.value=false;return}
 const previous=more?cursor.value:null,path='/directory/'+(featured.value?'featured-artists':'organizations')+query({city:city.value.trim(),q:term.value.trim(),cursor:previous,limit:20})
 if(featured.value){const r=await ui.read(path,isPage(isFeatured));if(n!==serial)return;if(r){if(previous!==null&&r.next_cursor===previous){ui.fail('分页位置没有更新，请重新查询。')}else{features.value=more?[...features.value,...r.items]:r.items;cursor.value=r.next_cursor;loaded.value=true}}}
 else{const r=await ui.read(path,isPage(isOrganization));if(n!==serial)return;if(r){if(previous!==null&&r.next_cursor===previous){ui.fail('分页位置没有更新，请重新查询。')}else{organizations.value=more?[...organizations.value,...r.items]:r.items;cursor.value=r.next_cursor;loaded.value=true}}}loading.value=false}
async function loadNotices(more=false){if(!organization.value||more&&!noticeCursor.value)return;const id=organization.value.party_id,previous=more?noticeCursor.value:null,r=await ui.read('/notices/catalog'+query({publisher_party_id:id,cursor:previous,limit:20}),isPage(isPublicItem));if(!r||organization.value?.party_id!==id)return;if(previous!==null&&previous===r.next_cursor){ui.fail('通告分页未更新，请刷新机构详情。');return}notices.value=more?[...notices.value,...r.items]:r.items;noticeCursor.value=r.next_cursor}
watch(ui.revision,()=>{clear();if(initialized&&ui.ready.value)void load()},{flush:'sync'})
watch(()=>[city.value,term.value],clear,{flush:'sync'})
</script>
<template><ServiceWorkspace :title="partyId?'机构公开资料':featured?'精选艺人':'公开机构'" intro="只展示当前已审且有效的公开资料。精选为运营推荐，不代表明星认证或排名。" account-only :error="error" :notice="notice" @ready="initialize"><template #heading><button class="outline" :disabled="loading" @click="load()">刷新当前资料</button></template><div class="service-tabs"><RouterLink to="/directory/organizations">公开机构</RouterLink><RouterLink to="/directory/featured">精选艺人</RouterLink><RouterLink to="/discovery">搜索内容</RouterLink><RouterLink to="/directory/manage">本机构公开资料</RouterLink></div><form v-if="!partyId" class="supply-card service-form" @submit.prevent="load()"><label>城市<input v-model="city" maxlength="100" placeholder="全部城市或具体名称"></label><label>名称或介绍<input v-model="term" type="search" maxlength="200"></label><button class="primary" :disabled="loading">查找当前资料</button></form><section class="supply-card"><p v-if="loading" role="status">正在读取当前获准资料…</p><template v-if="organization"><OrganizationCover :organization="organization" @invalid="organization=null;ui.fail('当前资料已不可读取，请刷新机构目录。')"/><h2>{{organization.display_name}}</h2><p>{{organization.city}} · {{organization.verified_capabilities.map(v=>capabilities[v]||v).join(' / ')}}</p><p class="service-text">{{organization.introduction}}</p><p class="service-muted">展示有效期 {{new Date(organization.valid_from).toLocaleString()}} 至 {{new Date(organization.valid_until).toLocaleString()}}</p><h2>该机构的公开通告</h2><article v-for="item in notices" :key="item.id" class="service-result"><h3>{{item.title||item.notice?.title}}</h3><p>{{item.description||item.notice?.description}}</p><RouterLink :to="publicLink('NOTICE',item.id)" class="button-link outline">查看通告</RouterLink></article><p v-if="!notices.length&&!noticeCursor&&!error">当前没有公开通告。</p><button v-if="noticeCursor" class="outline" @click="loadNotices(true)">继续读取机构通告</button></template><div v-else-if="!partyId" class="service-grid"><article v-for="item in organizations" :key="item.party_id" class="service-result"><h2>{{item.display_name}}</h2><p>{{item.city}} · {{item.verified_capabilities.map(v=>capabilities[v]||v).join(' / ')}}</p><p class="service-text">{{item.introduction}}</p><RouterLink :to="'/directory/organizations/'+item.party_id" class="button-link outline">机构资料与全部通告</RouterLink></article><article v-for="item in features" :key="item.record_id" class="service-result"><p class="service-muted">运营推荐 · {{item.artist.city}}</p><h2>{{item.artist.display_name}}</h2><p class="service-text">{{item.recommendation}}</p><RouterLink :to="publicLink('ARTIST',item.artist.listing_id)" class="button-link outline">查看当前艺人资料</RouterLink></article></div><p v-if="loaded&&!partyId&&!organizations.length&&!features.length&&!cursor&&!error">没有符合条件的当前公开资料。</p><p v-if="cursor&&!organizations.length&&!features.length">本页没有当前可见资料，可继续查找后续页。</p><button v-if="cursor" class="outline" :disabled="loading" @click="load(true)">继续查找</button></section></ServiceWorkspace></template>
